script:
frappe.ui.form.on('Employee Checkin', {
    time: run_logic,
    log_type: run_logic,
    shift: run_logic
});

function run_logic(frm) {

    if (!frm.doc.time || !frm.doc.shift) return;

    let log_type = frm.doc.log_type;
    let log_datetime = moment(frm.doc.time);

    // Reset fields
    frm.set_value("late_coming", null);
    frm.set_value("over_time", null);
    frm.set_value("holiday", 0);
    frm.set_value("absent", 0);

    frappe.db.get_doc('Shift Type', frm.doc.shift).then(shift => {

        let work_date = log_datetime.format("YYYY-MM-DD");

        // ================= IN =================
        if (log_type === "IN") {

            let shift_start = moment(
                work_date + " " + shift.start_time
            ).add(1, 'minutes'); // 1 minute grace

            if (log_datetime.isAfter(shift_start)) {
                let diff_sec = log_datetime.diff(shift_start, 'seconds');
                let late_time = moment.utc(diff_sec * 1000).format("HH:mm:ss");
                frm.set_value("late_coming", late_time);
            }
        }

        // ================= OUT =================
        else if (log_type === "OUT") {

            let shift_end = moment(
                work_date + " " + shift.end_time
            ).add(10, 'minutes'); // 10 min threshold

            if (log_datetime.isSameOrAfter(shift_end)) {
                let diff_sec = log_datetime.diff(shift_end, 'seconds');
                let ot_time = moment.utc(diff_sec * 1000).format("HH:mm:ss");
                frm.set_value("over_time", ot_time);
            }
        }

        // ================= EMPTY log_type =================
        else {

            if (!shift.holiday_list) {
                frm.set_value("absent", 1);
                return;
            }

            frappe.db.get_value('Holiday', {
                parent: shift.holiday_list,
                holiday_date: work_date
            }, 'name').then(r => {

                if (r.message) {
                    frm.set_value("holiday", 1);
                } else {
                    frm.set_value("absent", 1);
                }
            });
        }
    });
}

// پہلے debounce function بنائیں تاکہ ضرورت سے زیادہ calculations نہ ہوں
let calculationTimeout = null;

function debouncedCalculate(frm) {
    if (calculationTimeout) {
        clearTimeout(calculationTimeout);
    }
    
    calculationTimeout = setTimeout(() => {
        calculate_custom_amounts(frm);
    }, 100); // 100ms delay
}

// اصل event handlers - صرف ان events پر جو ضروری ہیں
frappe.ui.form.on('Salary Slip', {
    onload: function(frm) {
        setupForm(frm);
        calculate_custom_amounts(frm);
    },
    refresh: function(frm) {
        calculate_custom_amounts(frm);
    },
    // صرف وہ events جو data change کرتے ہیں
    earnings_add: function(frm) { debouncedCalculate(frm); },
    deductions_add: function(frm) { debouncedCalculate(frm); },
    earnings_remove: function(frm) { debouncedCalculate(frm); },
    deductions_remove: function(frm) { debouncedCalculate(frm); },
    
    // change events کو بھی debounce کریں
    earnings_amount: function(frm, cdt, cdn) { debouncedCalculate(frm); },
    earnings_salary_component: function(frm, cdt, cdn) { debouncedCalculate(frm); },
    deductions_amount: function(frm, cdt, cdn) { debouncedCalculate(frm); },
    deductions_salary_component: function(frm, cdt, cdn) { debouncedCalculate(frm); },
    
    // validate پر ایک بار final calculation
    before_save: function(frm) {
        // پہلے clear timeout
        if (calculationTimeout) {
            clearTimeout(calculationTimeout);
        }
        // فوری calculation
        calculate_custom_amounts(frm);
    }
});

function setupForm(frm) {
    // custom fields کو readonly بنا دیں تاکہ user نہ بدل سکے
    frm.set_df_property('custom_amount_1', 'read_only', 1);
    frm.set_df_property('custom_amount_2', 'read_only', 1);
    frm.set_df_property('custom_amount_3', 'read_only', 1);
}

function calculate_custom_amounts(frm) {
    if (!frm.doc.earnings) frm.doc.earnings = [];
    if (!frm.doc.deductions) frm.doc.deductions = [];

    // ===== Existing Earnings =====
    let basic = get_amount_safe(frm, 'Basic', 'earnings');
    let additional = get_amount_safe(frm, 'Additional Salary', 'earnings');
    let seniority = get_amount_safe(frm, 'Seniority Allowance', 'earnings');
    let appraisal = get_amount_safe(frm, 'Appraisal', 'earnings');
    let leave_encashment = get_amount_safe(frm, 'Leave Encashment', 'earnings');
    
    // ===== New Over Time Earnings (Added to Amount 1) =====
    let overTimeBasic = get_amount_safe(frm, 'Over Time Basic', 'earnings');
    let overTime125 = get_amount_safe(frm, 'Over Time 125%', 'earnings');
    let overTime150 = get_amount_safe(frm, 'Over Time 150%', 'earnings');
    let overTime175 = get_amount_safe(frm, 'Over Time 175%', 'earnings');
    
    // ===== Total Over Time =====
    let totalOverTime = overTimeBasic + overTime125 + overTime150 + overTime175;

    // ===== Existing Deductions =====
    let absent_deduction = get_amount_safe(frm, 'Absent Deduction', 'deductions');
    let penalty1 = get_amount_safe(frm, 'Penalty 1', 'deductions');
    let social_security = get_amount_safe(frm, 'Social Security', 'deductions');

    // ===== Waqf is now moved to Amount 3 =====
    let waqf = get_amount_safe(frm, 'Waqf', 'deductions');
    
    // ===== NEW: Employee Advance Deduction =====
    let employee_advance = get_amount_safe(frm, 'Employee Advance Deduction', 'deductions');

    // ===== custom_amount_1 (WITH Leave Encashment + Over Time and WITHOUT Waqf) =====
    let custom_amount_1 = 
        (basic + additional + seniority + appraisal + leave_encashment + totalOverTime)
        - (absent_deduction + penalty1);

    frappe.model.set_value(frm.doctype, frm.docname, 'custom_amount_1', custom_amount_1);

    // ===== custom_amount_2 (NOW WITH Employee Advance Deduction) =====
    let custom_amount_2 = custom_amount_1 - social_security - employee_advance;
    frappe.model.set_value(frm.doctype, frm.docname, 'custom_amount_2', custom_amount_2);

    // ===== custom_amount_3 (NOW INCLUDES Waqf after Income Tax) =====
    let add_total = safe_get_amount(frm, ['Special Allowance', 'Thank You Allowance'], 'earnings');
    let minus_total = safe_get_amount(frm, ['Income Tax', 'Late Entry', 'Penalty 2', 'Loan', 'Employee advance deduction'], 'deductions');
    
    // اب Waqf کو بھی minus_total میں شامل کریں گے
    minus_total += waqf;

    // ensure numbers only
    custom_amount_2 = isNaN(custom_amount_2) ? 0 : custom_amount_2;
    add_total = isNaN(add_total) ? 0 : add_total;
    minus_total = isNaN(minus_total) ? 0 : minus_total;

    // ===== NEW: Loans total_payment deduction (LAST STEP) =====
    let loans_total_payment = 0;
    
    if (frm.doc.loans && frm.doc.loans.length > 0) {
        frm.doc.loans.forEach(row => {
            loans_total_payment += parseFloat(row.total_payment || 0);
        });
    }
    
    // ===== Final custom_amount_3 Calculation =====
    let custom_amount_3 = (custom_amount_2 + add_total) - minus_total;
    
    // سب سے آخر میں loans بھی منفی کریں
    custom_amount_3 = custom_amount_3 - loans_total_payment;
    
    frappe.model.set_value(frm.doctype, frm.docname, 'custom_amount_3', custom_amount_3);

    
    // فوراً form کو refresh کریں
    frm.refresh_field('custom_amount_1');
    frm.refresh_field('custom_amount_2');
    frm.refresh_field('custom_amount_3');
}

// SAFE get single component
function get_amount_safe(frm, component_name, type) {
    let components = (type === 'earnings') ? frm.doc.earnings : frm.doc.deductions;
    if (!components) return 0;
    let total = 0;
    components.forEach(c => {
        if (c.salary_component && c.salary_component.trim() === component_name) {
            total += parseFloat(c.amount || 0);
        }
    });
    return total;
}

// SAFE get multiple components
function safe_get_amount(frm, component_list, type) {
    let total = 0;
    component_list.forEach(name => {
        total += get_amount_safe(frm, name, type);
    });
    return total;
}

frappe.ui.form.on('Monthly Attendance Summary', {
	onload: function(frm) {
		if (!frm.doc.month) {
			frm.set_value('month', new Date().getMonth() + 1);
		}
		if (!frm.doc.year) {
			frm.set_value('year', new Date().getFullYear());
		}
	},
	
	refresh: function(frm) {
		if (!frm.doc.__islocal) {
			frm.add_custom_button(__('Fetch Attendance'), function() {
				fetch_attendance_simple(frm);
			}).addClass('btn-primary');
		}
	}
});

function fetch_attendance_simple(frm) {
	if (!frm.doc.employee || !frm.doc.month || !frm.doc.year) {
		frappe.msgprint(__('Please set Employee, Month and Year first'));
		return;
	}
	
	frappe.show_progress(__('Fetching Data'), 0, 100, __('Please wait...'));
	
	// صرف Employee Checkin سے ڈیٹا حاصل کریں
	get_checkins_only(frm);
}

function get_checkins_only(frm) {
	const month_str = frm.doc.month.toString().padStart(2, '0');
	const from_date = `${frm.doc.year}-${month_str}-01`;
	const to_date = `${frm.doc.year}-${month_str}-31`;
	
	frappe.call({
		method: 'frappe.client.get_list',
		args: {
			doctype: 'Employee Checkin',
			filters: [
				['employee', '=', frm.doc.employee],
				['time', '>=', from_date],
				['time', '<=', to_date]
			],
			fields: ['time', 'log_type'],
			limit_page_length: 2000
		},
		callback: function(r) {
			frappe.hide_progress();
			
			if (r.message) {
				calculate_summary_simple(frm, r.message);
			} else {
				frappe.msgprint(__('No checkin data found'));
			}
		}
	});
}

function calculate_summary_simple(frm, checkins) {
	const year = parseInt(frm.doc.year);
	const month = parseInt(frm.doc.month);
	
	// Total days in month
	const last_day = new Date(year, month, 0).getDate();
	const total_days = last_day;
	
	// Fixed holidays (آپ یہاں اپنی holidays شامل کر سکتے ہیں)
	// فرض کریں کہ اتوار چھٹی ہوتی ہے
	const fixed_holidays = []; // آپ اس میں holidays شامل کر سکتے ہیں
	
	// Group checkins by day
	const daily_data = {};
	const present_days_set = new Set();
	
	checkins.forEach(checkin => {
		if (!checkin.time) return;
		
		const date = new Date(checkin.time);
		const day = date.getDate();
		
		// Mark this day as present
		present_days_set.add(day);
		
		if (!daily_data[day]) {
			daily_data[day] = [];
		}
		
		daily_data[day].push({
			time: date,
			log_type: checkin.log_type
		});
	});
	
	// Calculate Sundays as holidays
	let holidays_count = 0;
	let working_days = 0;
	let present_days = 0;
	let absent_days = 0;
	let late_minutes = 0;
	let overtime_hours = 0;
	
	for (let day = 1; day <= total_days; day++) {
		const date = new Date(year, month - 1, day);
		const day_of_week = date.getDay(); // 0 = Sunday
		
		// Check if Sunday
		if (day_of_week === 0) {
			holidays_count++;
		} else {
			working_days++;
			
			// Check if present
			if (present_days_set.has(day)) {
				present_days++;
				
				// Calculate for this day
				if (daily_data[day]) {
					const day_stats = calculate_day_stats_simple(daily_data[day]);
					late_minutes += day_stats.late_minutes;
					overtime_hours += day_stats.overtime_hours;
				}
			} else {
				absent_days++;
			}
		}
	}
	
	// Add fixed holidays
	holidays_count += fixed_holidays.length;
	
	// Convert late minutes to hours
	const late_hours = late_minutes / 60;
	
	// Update form
	frm.set_value('total_days', total_days);
	frm.set_value('holidays', holidays_count);
	frm.set_value('working_days', working_days);
	frm.set_value('present_days', present_days);
	frm.set_value('absent_days', absent_days);
	frm.set_value('late_coming_minutes', late_minutes);
	frm.set_value('overtime_hours', overtime_hours.toFixed(2));
	frm.set_value('late_coming_hours', late_hours.toFixed(2));
	
	frm.save();
	
	frappe.show_alert({
		message: __('Attendance calculated successfully!'),
		indicator: 'green'
	}, 5);
}

function calculate_day_stats_simple(day_checkins) {
	let late_minutes = 0;
	let overtime_hours = 0;
	
	// Sort by time
	day_checkins.sort((a, b) => a.time - b.time);
	
	let first_in = null;
	let last_out = null;
	
	for (const checkin of day_checkins) {
		if (checkin.log_type === 'IN' && !first_in) {
			first_in = checkin.time;
			
			// Calculate late coming (assuming shift starts at 9:00 AM)
			const shift_start = new Date(checkin.time);
			shift_start.setHours(9, 0, 0, 0);
			
			if (checkin.time > shift_start) {
				const late_ms = checkin.time - shift_start;
				late_minutes += Math.round(late_ms / (1000 * 60));
			}
		}
		
		if (checkin.log_type === 'OUT') {
			last_out = checkin.time;
		}
	}
	
	// Calculate overtime if we have both IN and OUT
	if (first_in && last_out) {
		const work_hours = (last_out - first_in) / (1000 * 60 * 60);
		
		// Overtime if worked more than 8 hours
		if (work_hours > 8) {
			overtime_hours += (work_hours - 8);
		}
	}
	
	return {
		late_minutes: late_minutes,
		overtime_hours: overtime_hours
	};
}

// Client Script for Salary Slip - Fixed Version with OT Fields
frappe.ui.form.on('Salary Slip', {
    employee: function(frm) {
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            fetch_attendance_simple(frm);
        }
    },

    start_date: function(frm) {
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            fetch_attendance_simple(frm);
        }
    },

    end_date: function(frm) {
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            fetch_attendance_simple(frm);
        }
    },

    refresh: function(frm) {
        if (frm.doc.docstatus === 0) {
            frm.add_custom_button(__('Fetch Attendance'), function() {
                fetch_attendance_simple(frm);
            }, __('Actions'));
            
            frm.add_custom_button(__('Clear Attendance'), function() {
                clear_attendance(frm);
            }, __('Actions'));
        }
    }
});

async function fetch_attendance_simple(frm) {
    if (!frm.doc.employee || !frm.doc.start_date) {
        frappe.msgprint(__('Please select employee and start date'));
        return;
    }
    
    frappe.show_alert({ message: __('Fetching attendance...'), indicator: 'blue' });
    
    let start_date = frappe.datetime.str_to_obj(frm.doc.start_date);
    let month_number = start_date.getMonth() + 1;
    let year = start_date.getFullYear();
    
    // Month names mapping
    const month_names = {
        1: 'January',
        2: 'February', 
        3: 'March',
        4: 'April',
        5: 'May',
        6: 'June',
        7: 'July',
        8: 'August',
        9: 'September',
        10: 'October',
        11: 'November',
        12: 'December'
    };
    
    let month_name = month_names[month_number];
    let month_name_lower = month_name.toLowerCase();
    
    try {
        // Fetch ONLY SUBMITTED records from Monthly Attendance Summary
        let records = await frappe.db.get_list('Monthly Attendance Summary', {
            filters: [
                ['employee', '=', frm.doc.employee],
                ['year', '=', year],
                ['docstatus', '=', 1] // ONLY SUBMITTED RECORDS
            ],
            fields: [
                'name', 
                'month', 
                'total_days', 
                'working_days', 
                'late_coming_hours', 
                'absent_days', 
                'present_days',
                'ot_with_basic_rate',
                'ot_on_125_rate',
                'ot_on_150_rate',
                'ot_on_175_rate'
            ],
            limit: 12
        });
        
        if (!records || records.length === 0) {
            frappe.msgprint({
                title: __('No Submitted Data Found'),
                message: __('No SUBMITTED attendance records found for ') + frm.doc.employee + __(' in ') + year + __('<br><br>Only submitted Monthly Attendance Summary records will be fetched.'),
                indicator: 'orange'
            });
            return;
        }
        
        // Try to find match
        let found_record = null;
        
        for (let record of records) {
            if (record.month) {
                let record_month_lower = record.month.toString().trim().toLowerCase();
                
                // Exact match
                if (record_month_lower === month_name_lower) {
                    found_record = record;
                    break;
                }
                
                // Partial match (first 3 letters)
                if (record_month_lower.substring(0, 3) === month_name_lower.substring(0, 3)) {
                    found_record = record;
                    break;
                }
            }
        }
        
        if (found_record) {
            // Update all fields
            frm.set_value('custom_monthly_attendance', found_record.name);
            frm.set_value('custom_employees_name', frm.doc.employee);
            frm.set_value('custom_total_days', found_record.total_days || 0);
            frm.set_value('total_working_days', found_record.working_days || 0);
            frm.set_value('custom_late_hours', found_record.late_coming_hours || 0);
            frm.set_value('custom_total_absent_days', found_record.absent_days || 0);
            frm.set_value('custom_present_days', found_record.present_days || 0);
            
            // Update OT fields
            frm.set_value('ot_with_basic_rate', found_record.ot_with_basic_rate || 0);
            frm.set_value('ot_on_125_rate', found_record.ot_on_125_rate || 0);
            frm.set_value('ot_on_150_rate', found_record.ot_on_150_rate || 0);
            frm.set_value('ot_on_175_rate', found_record.ot_on_175_rate || 0);
            
            frappe.show_alert({
                message: __('Submitted attendance data fetched successfully'),
                indicator: 'green'
            });
        } else {
            frappe.msgprint({
                title: __('Month Not Found'),
                message: __('No matching SUBMITTED attendance record found for ') + month_name + ' ' + year,
                indicator: 'red'
            });
        }
        
    } catch (error) {
        frappe.msgprint(__('Error: ') + error.message);
    }
}

function clear_attendance(frm) {
    // Clear all fields including OT fields
    frm.set_value('custom_monthly_attendance', '');
    frm.set_value('custom_employees_name', '');
    frm.set_value('custom_total_days', 0);
    frm.set_value('total_working_days', 0);
    frm.set_value('custom_late_hours', 0);
    frm.set_value('custom_total_absent_days', 0);
    frm.set_value('custom_present_days', 0);
    frm.set_value('ot_with_basic_rate', 0);
    frm.set_value('ot_on_125_rate', 0);
    frm.set_value('ot_on_150_rate', 0);
    frm.set_value('ot_on_175_rate', 0);
}

frappe.ui.form.on("Monthly Attendance Summary", {

    ot_with_basic_rate: calculate_ot,
    ot_on_125_rate: calculate_ot,
    ot_on_150_rate: calculate_ot,
    ot_on_175_rate: calculate_ot,
    overtime_hours: calculate_ot
});

function calculate_ot(frm) {

    let overtime = flt(frm.doc.overtime_hours || 0);

    let approved = 
        flt(frm.doc.ot_with_basic_rate || 0) +
        flt(frm.doc.ot_on_125_rate || 0) +
        flt(frm.doc.ot_on_150_rate || 0) +
        flt(frm.doc.ot_on_175_rate || 0);

    frm.set_value("approved_ot_hrs", approved);

    let remaining = overtime - approved;

    if (remaining < 0) {
        frappe.msgprint("You cannot approve more hours than available overtime hours.");

        frm.set_value("ot_with_basic_rate", 0);
        frm.set_value("ot_on_125_rate", 0);
        frm.set_value("ot_on_150_rate", 0);
        frm.set_value("ot_on_175_rate", 0);

        frm.set_value("approved_ot_hrs", 0);
        frm.set_value("not_approved_ot_hrs", overtime);

        return;
    }

    frm.set_value("not_approved_ot_hrs", remaining);
}

frappe.ui.form.on('Salary Structure Assignment', {
    refresh: function(frm) {
        set_leave_encashment_amount(frm);
    },
    
    employee: function(frm) {
        set_leave_encashment_amount(frm);
    }
});

function set_leave_encashment_amount(frm) {
    // اگر ایمپلائے منتخب نہیں ہے تو خالی کر دیں
    if (!frm.doc.employee) {
        frm.set_value('leave_encashment_amount_per_day', '');
        return;
    }
    
    // ایمپلائے ڈاکومنٹ سے basic_salary لائیں
    frappe.db.get_value('Employee', frm.doc.employee, 'basic_salary')
        .then(r => {
            if (r.message && r.message.basic_salary) {
                let basic_salary = r.message.basic_salary;
                // basic_salary کو 30 سے تقسیم کریں
                let amount_per_day = basic_salary / 30;
                
                // اعشاریہ کے بعد 2 ڈیجٹ تک round کریں، تیسرے نمبر کی بنیاد پر
                let rounded_amount = round_to_two_decimals(amount_per_day);
                
                // فیلڈ میں ویلیو سیٹ کریں
                frm.set_value('leave_encashment_amount_per_day', rounded_amount);
            } else {
                frm.set_value('leave_encashment_amount_per_day', '');
            }
        })
        .catch(err => {
            console.log(err);
            frappe.msgprint(__('ایمپلائے کی basic_salary حاصل کرنے میں خرابی ہوئی'));
        });
}

function round_to_two_decimals(value) {
    // نمبر کو 1000 سے ضرب دیں تاکہ اعشاریہ کے 3 ڈیجٹ حاصل ہوں
    let scaled_value = value * 1000;
    
    // پورے حصے اور اعشاریہ کے حصے کو الگ کریں
    let integer_part = Math.floor(scaled_value / 1000);
    let decimal_part = scaled_value % 1000;
    
    // اعشاریہ کے 3 ڈیجٹ کو الگ کریں
    let first_decimal = Math.floor(decimal_part / 100);
    let second_decimal = Math.floor((decimal_part % 100) / 10);
    let third_decimal = decimal_part % 10;
    
    // اگر تیسرا ڈیجٹ 5 یا اس سے بڑا ہو تو دوسرے ڈیجٹ کو 1 بڑھائیں
    if (third_decimal >= 5) {
        second_decimal = second_decimal + 1;
        
        // اگر دوسرا ڈیجٹ 10 ہو جائے تو اسے 0 کریں اور پہلے ڈیجٹ کو 1 بڑھائیں
        if (second_decimal === 10) {
            second_decimal = 0;
            first_decimal = first_decimal + 1;
            
            // اگر پہلا ڈیجٹ 10 ہو جائے تو اسے 0 کریں اور پورے حصے کو 1 بڑھائیں
            if (first_decimal === 10) {
                first_decimal = 0;
                integer_part = integer_part + 1;
            }
        }
    }
    
    // دوبارہ نمبر بنا لیں
    let rounded_value = integer_part + (first_decimal / 100) + (second_decimal / 1000);
    
    // 2 اعشاریہ ڈیجٹ تک محدود کریں
    return Number(rounded_value.toFixed(2));
}

frappe.ui.form.on('Full and Final Statement', {
    total_payable_amount: function(frm) {
        calculate_total(frm);
    },

    total_receivable_amount: function(frm) {
        calculate_total(frm);
    },

    total_asset_recovery_cost: function(frm) {
        calculate_total(frm);
    },

    refresh: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    let payable = frm.doc.total_payable_amount || 0;
    let receivable = frm.doc.total_receivable_amount || 0;
    let asset_cost = frm.doc.total_asset_recovery_cost || 0;

    let total = payable - receivable - asset_cost;

    frm.set_value('total_amount', total);
}
